class LamportClock {
  constructor() {
    this.counter = 0;
  }

  // Call before any local event
  tick() {
    this.counter += 1;
    return this.counter;
  }

  // Call when sending a message, attach the returned value
  onSend() {
    this.counter += 1;
    return this.counter;
  }

  // Call when receiving a message carrying remoteCounter
  onReceive(remoteCounter) {
    this.counter = Math.max(this.counter, remoteCounter) + 1;
    return this.counter;
  }
}

